export const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),lerp=(a,b,t)=>a+(b-a)*t,wrap=(v,n)=>((v%n)+n)%n,angleDiff=(a,b)=>Math.atan2(Math.sin(a-b),Math.cos(a-b));
const controls=[[0,0],[240,0],[430,0],[550,100],[520,270],[380,330],[310,220],[170,210],[100,360],[-100,390],[-300,290],[-370,100],[-270,-70],[-100,-80]].map(p=>p.map(v=>v*1.45));
const raw=[];for(let i=0;i<controls.length;i++)for(let j=0;j<80;j++){let t=j/80,p0=controls[wrap(i-1,controls.length)],p1=controls[i],p2=controls[(i+1)%controls.length],p3=controls[(i+2)%controls.length];raw.push([0,1].map(k=>.5*(2*p1[k]+(-p0[k]+p2[k])*t+(2*p0[k]-5*p1[k]+4*p2[k]-p3[k])*t*t+(-p0[k]+3*p1[k]-3*p2[k]+p3[k])*t*t*t)));}
let length=0;const cumulative=[0];for(let i=0;i<raw.length;i++){let b=raw[(i+1)%raw.length];length+=Math.hypot(b[0]-raw[i][0],b[1]-raw[i][1]);cumulative.push(length);}export const LENGTH=length,HALF=9.5,COUNT=1200;
function rawSample(d){d=wrap(d,LENGTH);let lo=0,hi=raw.length-1;while(lo<hi){let m=(lo+hi+1)>>1;if(cumulative[m]<=d)lo=m;else hi=m-1;}let a=raw[lo],b=raw[(lo+1)%raw.length],t=(d-cumulative[lo])/(cumulative[lo+1]-cumulative[lo]);return{x:lerp(a[0],b[0],t),z:lerp(a[1],b[1],t)};}
export const path=Array.from({length:COUNT},(_,i)=>rawSample(i/COUNT*LENGTH));for(let i=0;i<COUNT;i++){let p=path[i],q=path[(i+1)%COUNT];p.tx=q.x-p.x;p.tz=q.z-p.z;let l=Math.hypot(p.tx,p.tz);p.tx/=l;p.tz/=l;p.a=Math.atan2(p.tx,p.tz);p.d=i/COUNT*LENGTH;}for(let i=0;i<COUNT;i++){let p=path[i],a=path[wrap(i-3,COUNT)],b=path[(i+3)%COUNT];p.curve=Math.abs(angleDiff(b.a,a.a))/(6*LENGTH/COUNT);p.limit=clamp(Math.sqrt(21/Math.max(.001,p.curve)),23,87);}for(let k=0;k<3;k++)for(let i=COUNT-1;i>=0;i--)path[i].limit=Math.min(path[i].limit,Math.sqrt(path[(i+1)%COUNT].limit**2+2*11*LENGTH/COUNT));
export function sample(d,offset=0){let f=wrap(d,LENGTH)/LENGTH*COUNT,i=Math.floor(f),p=path[i],q=path[(i+1)%COUNT],t=f-i,a=p.a+angleDiff(q.a,p.a)*t;return{x:lerp(p.x,q.x,t)+Math.cos(a)*offset,z:lerp(p.z,q.z,t)-Math.sin(a)*offset,a,limit:lerp(p.limit,q.limit,t),curve:p.curve};}
export function nearest(x,z,hint=null){let best={dist:Infinity},search=(i)=>{i=wrap(i,COUNT);let p=path[i],q=path[(i+1)%COUNT],dx=q.x-p.x,dz=q.z-p.z,t=clamp(((x-p.x)*dx+(z-p.z)*dz)/(dx*dx+dz*dz),0,1),px=p.x+dx*t,pz=p.z+dz*t,dist=Math.hypot(x-px,z-pz);if(dist<best.dist)best={dist,x:px,z:pz,i,d:(i+t)/COUNT*LENGTH,a:p.a,limit:p.limit,offset:(x-px)*Math.cos(p.a)-(z-pz)*Math.sin(p.a)};};if(hint!==null){for(let j=-22;j<=22;j++)search(hint+j);if(best.dist<30)return best;}for(let i=0;i<COUNT;i++)search(i);return best;}
export function createCar(distance=0,offset=0){let p=sample(distance,offset);return{x:p.x,z:p.z,a:p.a,vx:0,vz:0,yaw:0,steer:0,speed:0,distance,near:nearest(p.x,p.z),ers:100,throttle:0,brake:0,offTime:0,invalid:false,lapTime:0,best:0,completed:0,lastD:wrap(distance,LENGTH),stuck:0,collisionCooldown:0,finished:false};}
export function drive(car,input,dt,assist=true){let n=nearest(car.x,car.z,car.near?.i);car.near=n;let grass=n.dist>HALF+.3,runoff=n.dist>HALF+1.4;let fwdX=Math.sin(car.a),fwdZ=Math.cos(car.a),rightX=Math.cos(car.a),rightZ=-Math.sin(car.a),u=car.vx*fwdX+car.vz*fwdZ,v=car.vx*rightX+car.vz*rightZ,speed=Math.hypot(u,v);let gas=clamp(input.gas||0,0,1),brake=clamp(input.brake||0,0,1);if(assist&&speed>n.limit*1.05){brake=Math.max(brake,clamp((speed-n.limit*1.05)/12,0,.9));gas*=1-brake;}car.throttle=lerp(car.throttle,gas,Math.min(1,dt*10));car.brake=lerp(car.brake,brake,Math.min(1,dt*18));let steerMax=.49/(1+speed/27);car.steer=lerp(car.steer,clamp(input.steer||0,-1,1)*steerMax,Math.min(1,dt*(assist?9:7)));let mu=runoff?.55:grass?1.05:1.65,down=2.6*speed*speed,available=mu*(9.81+down/798);let boost=input.boost&&car.ers>0&&car.throttle>.3&&!runoff;car.ers=clamp(car.ers+dt*(boost?-22:car.brake*9+2.2),0,100);let engine=Math.min(14,(boost?560:445)/Math.max(15,speed));let drag=.00085*u*Math.abs(u)+(runoff?3.7:.18)*Math.sign(u);let accel=car.throttle*engine-car.brake*(runoff?9:24)*Math.sign(u||1)-drag;if(car.brake>.1&&Math.abs(u)<.25)u=0;let lateralWanted=u/3.6*Math.tan(car.steer),yawLimit=available/Math.max(6,speed),yawTarget=clamp(lateralWanted,-yawLimit,yawLimit);car.yaw=lerp(car.yaw,yawTarget,Math.min(1,dt*(assist?8:5)));let gripRate=clamp(available/(Math.abs(v)+1),1,16);let du=accel+v*car.yaw,dv=-v*gripRate-u*car.yaw;let nu=u+du*dt;if(car.brake>.05&&u>=0&&nu<0)nu=0;nu=clamp(nu,-1,95);v+=dv*dt;car.a+=car.yaw*dt;fwdX=Math.sin(car.a);fwdZ=Math.cos(car.a);rightX=Math.cos(car.a);rightZ=-Math.sin(car.a);car.vx=fwdX*nu+rightX*v;car.vz=fwdZ*nu+rightZ*v;car.x+=car.vx*dt;car.z+=car.vz*dt;car.speed=Math.hypot(car.vx,car.vz);car.collisionCooldown=Math.max(0,car.collisionCooldown-dt);car.offTime=runoff?car.offTime+dt:0;car.invalid ||= grass;
// Tangential progress is bounded by actual movement; teleporting never grants a lap.
let delta=n.d-car.lastD;if(delta>LENGTH/2)delta-=LENGTH;if(delta<-LENGTH/2)delta+=LENGTH;if(Math.abs(delta)<Math.max(2,speed*dt*4)&&!runoff)car.distance+=delta;car.lastD=n.d;car.lapTime+=dt;let completed=Math.max(0,Math.floor(car.distance/LENGTH));if(completed>car.completed){car.completed=completed;car.justLapped={time:car.lapTime,valid:!car.invalid};if(!car.invalid&&(!car.best||car.lapTime<car.best))car.best=car.lapTime;car.lapTime=0;car.invalid=false;}if(n.dist>HALF+14){let nx=Math.cos(n.a)*Math.sign(n.offset),nz=-Math.sin(n.a)*Math.sign(n.offset),out=car.vx*nx+car.vz*nz;if(out>0){car.vx-=out*nx*1.4;car.vz-=out*nz*1.4;}car.x=n.x+nx*(HALF+13.8);car.z=n.z+nz*(HALF+13.8);car.speed*=.65;car.wallHit=true;}}
export function recover(car){let p=sample(car.distance,0);Object.assign(car,{x:p.x,z:p.z,a:p.a,vx:0,vz:0,yaw:0,speed:0,steer:0,near:nearest(p.x,p.z),offTime:0,invalid:true,lastD:wrap(car.distance,LENGTH)});}
export function collide(a,b){let dx=b.x-a.x,dz=b.z-a.z,len=Math.hypot(dx,dz);if(len>3.3||len<.01)return false;let nx=dx/len,nz=dz/len,overlap=3.3-len;a.x-=nx*overlap*.5;a.z-=nz*overlap*.5;b.x+=nx*overlap*.5;b.z+=nz*overlap*.5;let relative=(a.vx-b.vx)*nx+(a.vz-b.vz)*nz;if(relative>0){let impulse=relative*.65;a.vx-=impulse*nx;a.vz-=impulse*nz;b.vx+=impulse*nx;b.vz+=impulse*nz;}return relative>1;}
